changeSet.sql:
DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'superset_ro') THEN
    GRANT USAGE ON SCHEMA core, analytics TO superset_ro;
    GRANT SELECT ON ALL TABLES IN SCHEMA core, analytics TO superset_ro;
    ALTER DEFAULT PRIVILEGES IN SCHEMA core
      GRANT SELECT ON TABLES TO superset_ro;
    ALTER DEFAULT PRIVILEGES IN SCHEMA analytics
      GRANT SELECT ON TABLES TO superset_ro;
  END IF;
END
$$;

rollback.sql:
DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'superset_ro') THEN
    REVOKE ALL ON ALL TABLES IN SCHEMA core, analytics FROM superset_ro;
    REVOKE USAGE ON SCHEMA core, analytics FROM superset_ro;
  END IF;
END
$$;
